/* From Uiverse.io by fanishah - Tags: loader */
.__UIV_SCOPE__ .gegga {
  width: 0;
}

.__UIV_SCOPE__ .snurra {
  filter: url(#gegga);
}

.__UIV_SCOPE__ .stopp1 {
  stop-color: #f700a8;
}

.__UIV_SCOPE__ .stopp2 {
  stop-color: #ff8000;
}

.__UIV_SCOPE__ .halvan {
  animation: Snurra1 10s infinite linear;
  stroke-dasharray: 180 800;
  fill: none;
  stroke: url(#gradient);
  stroke-width: 23;
  stroke-linecap: round;
}

.__UIV_SCOPE__ .strecken {
  animation: Snurra1 3s infinite linear;
  stroke-dasharray: 26 54;
  fill: none;
  stroke: url(#gradient);
  stroke-width: 23;
  stroke-linecap: round;
}

.__UIV_SCOPE__ .skugga {
  filter: blur(5px);
  opacity: 0.3;
  position: absolute;
  transform: translate(3px, 3px);
}

@keyframes Snurra1 {
  0% {
    stroke-dashoffset: 0;
  }

  100% {
    stroke-dashoffset: -403px;
  }
}
